CREATE DATABASE IF NOT EXISTS shinning_buddies;USE shinning_buddies;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150) UNIQUE,password_hash VARCHAR(100),role ENUM('admin','sales','inventory','technician') DEFAULT 'admin');
CREATE TABLE customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(20),email VARCHAR(150),address VARCHAR(255),city VARCHAR(80),capacity_kw DECIMAL(6,2),stage VARCHAR(40) DEFAULT 'Enquiry',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE site_surveys(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,surveyor_id INT,roof_type VARCHAR(60),shadow_free_area DECIMAL(8,2),notes TEXT,status VARCHAR(30) DEFAULT 'Pending',surveyed_on DATE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE packages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),panels INT,panel_watt INT DEFAULT 540,inverter VARCHAR(80),price DECIMAL(12,2),description TEXT);
CREATE TABLE quotations(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,package_id INT,bom JSON,subtotal DECIMAL(12,2) DEFAULT 0,gst DECIMAL(12,2) DEFAULT 0,total DECIMAL(12,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'Draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE SET NULL);
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,quotation_id INT,amount DECIMAL(12,2),method VARCHAR(30),status VARCHAR(20) DEFAULT 'Pending',paid_on DATE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE inventory_items(id INT AUTO_INCREMENT PRIMARY KEY,item VARCHAR(120),category VARCHAR(30),serial_range VARCHAR(60),serial_seq_end INT DEFAULT 0,quantity INT DEFAULT 0,status VARCHAR(20) DEFAULT 'In stock');
CREATE TABLE technicians(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),phone VARCHAR(20),crew VARCHAR(30),jobs_done INT DEFAULT 0,status VARCHAR(20) DEFAULT 'Active');
CREATE TABLE installations(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,technician_id INT,crew VARCHAR(30),start_date DATE,status VARCHAR(30) DEFAULT 'Scheduled',photos JSON,signature VARCHAR(255),FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE dispatches(id INT AUTO_INCREMENT PRIMARY KEY,installation_id INT,site VARCHAR(150),vehicle VARCHAR(30),status VARCHAR(20) DEFAULT 'Scheduled',dispatched_on DATE);
CREATE TABLE warranties(id INT AUTO_INCREMENT PRIMARY KEY,installation_id INT,customer_id INT,item VARCHAR(80),valid_from DATE,valid_until DATE,status VARCHAR(20) DEFAULT 'Active');
CREATE TABLE service_tickets(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,installation_id INT,issue VARCHAR(255),priority VARCHAR(20) DEFAULT 'Normal',status VARCHAR(20) DEFAULT 'Open',assigned_to INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE finance_entries(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150),category VARCHAR(30),amount DECIMAL(12,2),status VARCHAR(20) DEFAULT 'Pending',entry_date DATE);
CREATE TABLE subsidies(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,scheme VARCHAR(80),status VARCHAR(20) DEFAULT 'Submitted',applied_on DATE,notes TEXT,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
